CREATE TABLE IF NOT EXISTS workforce_presence_evidence(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,employee_email TEXT NOT NULL,punch_type TEXT NOT NULL,captured_at TEXT NOT NULL,latitude REAL,longitude REAL,accuracy_meters REAL,media_object_key TEXT,media_sha256 TEXT,liveness_status TEXT NOT NULL DEFAULT 'NOT_CONFIGURED',face_verification_status TEXT NOT NULL DEFAULT 'NOT_PERFORMED',device_evidence_json TEXT NOT NULL DEFAULT '{}',decision TEXT NOT NULL DEFAULT 'MANAGER_REVIEW',reviewed_by TEXT,reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS workforce_presence_exceptions(id TEXT PRIMARY KEY,presence_evidence_id TEXT NOT NULL,exception_type TEXT NOT NULL,severity TEXT NOT NULL,detail_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',notified_at TEXT,resolved_by TEXT,resolved_at TEXT,FOREIGN KEY(presence_evidence_id) REFERENCES workforce_presence_evidence(id));
CREATE TABLE IF NOT EXISTS reputation_journeys(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,guest_reference TEXT NOT NULL,stay_reference TEXT,consent_status TEXT NOT NULL DEFAULT 'UNKNOWN',stage TEXT NOT NULL DEFAULT 'PRE_STAY',sentiment_score REAL,last_contact_at TEXT,next_action_at TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reputation_contact_drafts(id TEXT PRIMARY KEY,journey_id TEXT NOT NULL,contact_type TEXT NOT NULL,channel TEXT NOT NULL,message_text TEXT NOT NULL,public_review_opportunity INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'DRAFT',approval_status TEXT NOT NULL DEFAULT 'PENDING',sent_at TEXT,created_at TEXT NOT NULL,FOREIGN KEY(journey_id) REFERENCES reputation_journeys(id));
CREATE TABLE IF NOT EXISTS reputation_recovery_cases(id TEXT PRIMARY KEY,journey_id TEXT NOT NULL,issue_category TEXT NOT NULL,severity TEXT NOT NULL,owner_role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',sla_due_at TEXT NOT NULL,resolution_note TEXT,closed_at TEXT,FOREIGN KEY(journey_id) REFERENCES reputation_journeys(id));
CREATE INDEX IF NOT EXISTS idx_presence_scope ON workforce_presence_evidence(organization_id,property_id,employee_email,captured_at);
CREATE INDEX IF NOT EXISTS idx_reputation_scope ON reputation_journeys(organization_id,property_id,status,next_action_at);
